"use client";

import Image from "next/image";
import { ChevronRight, Expand, Images } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import archiveData from "@/public/data/klr-archive.json";
import media from "@/data/media.generated.json";
import { MediaDialog } from "@/components/ui/media-dialog";

type FormatName = keyof typeof archiveData.formats;
type CenturyFilter = "ALL" | FormatName;

export function CenturyVaultSection() {
  const [filter, setFilter] = useState<CenturyFilter>("ALL");
  const [selected, setSelected] = useState(0);
  const [visibleCount, setVisibleCount] = useState(9);
  const [dialogOpen, setDialogOpen] = useState(false);
  const filtered = useMemo(() => archiveData.centuries.filter((century) => filter === "ALL" || century.format === filter), [filter]);
  const currentIndex = Math.min(selected, Math.max(filtered.length - 1, 0));
  const current = filtered[currentIndex];
  const currentImage = media.centuries[currentIndex % media.centuries.length];

  useEffect(() => {
    setSelected(0);
    setVisibleCount(9);
  }, [filter]);

  function move(step: number) {
    setSelected((value) => (value + step + filtered.length) % filtered.length);
  }

  return (
    <section id="centuries" className="century-section" aria-labelledby="century-title">
      <div className="section-heading split-heading">
        <div className="eyebrow">03 / {archiveData.centuries.length} dataset centuries</div>
        <h2 id="century-title">CENTURY <i>VAULT</i></h2>
        <p>Scores and context come from delivery data. The photographs are era-grouped archive imagery and are not presented as exact match photographs.</p>
      </div>
      <div className="format-tabs" role="tablist" aria-label="Century format">
        {(["ALL", "Test", "ODI", "T20I", "IPL"] as CenturyFilter[]).map((item) => (
          <button type="button" role="tab" aria-selected={filter === item} onClick={() => setFilter(item)} key={item}>{item}</button>
        ))}
      </div>
      {current && (
        <div className="century-feature">
          <button className="century-feature-image" type="button" onClick={() => setDialogOpen(true)} aria-label={`Open details for ${current.runs} against ${current.opponent}`}>
            <Image
              key={currentImage.src}
              src={currentImage.src}
              alt={`KL Rahul — ${currentImage.era.toLowerCase()} archive photograph`}
              fill
              sizes="(max-width: 900px) 92vw, 62vw"
              loading="lazy"
            />
            <span><Expand aria-hidden="true" /> Open innings</span>
          </button>
          <div className="century-feature-score">
            <span>{current.format} · {current.date}</span>
            <strong>{current.runs}</strong>
            <h3>vs {current.opponent}</h3>
            <p>{current.venue}</p>
            <div className="innings-context">
              <span>{current.balls} balls</span>
              <span>SR {current.strike_rate}</span>
              <span>{current.fours}×4 · {current.sixes}×6</span>
              <span>Impact {current.impact_score}</span>
            </div>
          </div>
        </div>
      )}
      <div className="century-grid">
        {filtered.slice(0, visibleCount).map((century, index) => {
          const image = media.centuries[index % media.centuries.length];
          return (
            <button
              className={index === currentIndex ? "century-card selected" : "century-card"}
              type="button"
              onClick={() => {
                setSelected(index);
                setDialogOpen(true);
              }}
              key={`${century.match_id}-${century.innings_number}`}
            >
              <div>
                <Image src={image.src} alt="" fill sizes="(max-width: 680px) 92vw, (max-width: 1100px) 46vw, 30vw" loading="lazy" aria-hidden="true" />
              </div>
              <span>{String(index + 1).padStart(2, "0")} · {century.format}</span>
              <strong>{century.runs}</strong>
              <p>vs {century.opponent}</p>
              <small>{century.date}</small>
              <ChevronRight aria-hidden="true" />
            </button>
          );
        })}
      </div>
      {visibleCount < filtered.length && (
        <button className="outline-action" type="button" onClick={() => setVisibleCount(filtered.length)}>
          Show all {filtered.length} innings <ChevronRight aria-hidden="true" />
        </button>
      )}
      {current && (
        <MediaDialog open={dialogOpen} titleId="century-dialog-title" onClose={() => setDialogOpen(false)} onPrevious={() => move(-1)} onNext={() => move(1)}>
          <div className="century-dialog-image">
            <Image src={currentImage.src} alt={`KL Rahul — ${currentImage.era.toLowerCase()} archive photograph`} fill sizes="90vw" />
          </div>
          <div className="century-dialog-copy">
            <span>{current.format} · {current.date}</span>
            <h2 id="century-dialog-title">{current.runs} <i>vs {current.opponent}</i></h2>
            <p>{current.venue}</p>
            <dl>
              <div><dt>Balls</dt><dd>{current.balls}</dd></div>
              <div><dt>Strike rate</dt><dd>{current.strike_rate}</dd></div>
              <div><dt>Boundaries</dt><dd>{current.fours}×4 · {current.sixes}×6</dd></div>
              <div><dt>Result</dt><dd>{current.result}</dd></div>
            </dl>
            <small>Match data is verified from the supplied Cricsheet coverage. The accompanying photograph is era-level archive imagery.</small>
          </div>
        </MediaDialog>
      )}
    </section>
  );
}

export function GallerySection() {
  const [filter, setFilter] = useState("all");
  const [visibleCount, setVisibleCount] = useState(24);
  const [selected, setSelected] = useState<number | null>(null);
  const filtered = useMemo(() => filter === "all" ? media.gallery : media.gallery.filter((image) => image.category === filter), [filter]);
  const active = selected === null ? null : filtered[selected];

  useEffect(() => {
    setVisibleCount(filter === "all" ? 24 : 20);
    setSelected(null);
  }, [filter]);

  function move(step: number) {
    if (selected === null) return;
    setSelected((selected + step + filtered.length) % filtered.length);
  }

  return (
    <section id="gallery" className="gallery-section" aria-labelledby="gallery-title">
      <div className="section-heading gallery-heading">
        <div className="eyebrow">05 / 79 archive photographs</div>
        <h2 id="gallery-title">FRAME <i>BY FRAME</i></h2>
        <p>Natural aspect ratios are preserved. Filter by chronological era, then open any photograph in the keyboard-accessible lightbox.</p>
      </div>
      <div className="gallery-toolbar" aria-label="Gallery era filter">
        <button type="button" aria-pressed={filter === "all"} onClick={() => setFilter("all")}>All <span>79</span></button>
        {media.categories.map((category) => {
          const count = media.gallery.filter((image) => image.category === category.id).length;
          return <button type="button" aria-pressed={filter === category.id} onClick={() => setFilter(category.id)} key={category.id}>{category.shortLabel} <span>{count}</span></button>;
        })}
      </div>
      <div className="masonry-gallery">
        {filtered.slice(0, visibleCount).map((image, index) => (
          <figure className="gallery-item" key={image.id}>
            <button type="button" onClick={() => setSelected(index)} aria-label={`Open ${image.era.toLowerCase()} archive image ${index + 1}`}>
              <Image
                src={image.src}
                alt={image.alt}
                width={image.width}
                height={image.height}
                sizes="(max-width: 560px) 92vw, (max-width: 960px) 46vw, 30vw"
                loading="lazy"
              />
              <span><Expand aria-hidden="true" /></span>
            </button>
            <figcaption><span>{String(image.index).padStart(2, "0")}</span>{image.era}</figcaption>
          </figure>
        ))}
      </div>
      {visibleCount < filtered.length && (
        <button className="outline-action gallery-more" type="button" onClick={() => setVisibleCount((value) => Math.min(value + 24, filtered.length))}>
          <Images aria-hidden="true" /> Load more photographs <span>{visibleCount} / {filtered.length}</span>
        </button>
      )}
      {active && (
        <MediaDialog open={selected !== null} titleId="gallery-dialog-title" onClose={() => setSelected(null)} onPrevious={() => move(-1)} onNext={() => move(1)}>
          <div className="lightbox-image">
            <Image src={active.src} alt={active.alt} fill sizes="96vw" />
          </div>
          <div className="lightbox-caption">
            <span>{String((selected ?? 0) + 1).padStart(2, "0")} / {filtered.length}</span>
            <h2 id="gallery-dialog-title">{active.era}</h2>
            <p>Era-level archive photograph. Exact match metadata is not available in the supplied manifest.</p>
          </div>
        </MediaDialog>
      )}
    </section>
  );
}
