function JourneyConnector({ index }: { index: number }) {
  if (index === journeyStages.length - 1) return null;
  const pattern = index % 4;
  const desktopPaths = [
    "M4 54 C42 10 92 96 146 50",
    "M18 5 C138 18 132 104 58 146",
    "M146 54 C104 10 56 96 4 50",
    "M140 5 C22 18 28 104 102 146",
  ];
  return (
    <>
      <motion.svg className={`journey-link journey-link-${pattern}`} viewBox="0 0 150 155" aria-hidden="true">
        <motion.path d={desktopPaths[pattern]} initial={{ pathLength: 0.15 }} whileInView={{ pathLength: 1 }} viewport={{ once: true, amount: 0.35 }} transition={{ duration: 0.8 }} />
        <path className="journey-link-arrow" d={pattern === 0 ? "M136 39 L147 50 L133 56" : pattern === 1 ? "M69 137 L58 147 L54 132" : pattern === 2 ? "M17 39 L4 50 L18 57" : "M91 137 L102 147 L106 132"} />
      </motion.svg>
      <svg className="journey-link-mobile" viewBox="0 0 80 64" aria-hidden="true"><path d="M38 2 C72 18 9 38 43 61" /><path d="M34 51 L43 61 L50 51" /></svg>
    </>
  );
}

